#include <string>

class Solution {
public:
    int minFlips(std::string target) {
        char curState = '0';
        int flips = 0;
        for (char ch : target) {
            if (ch != curState) {
                flips++;
                curState = ch;
            }
        }
        return flips;
    }
};

class Solution {
    public int minFlips(String target) {
        char curState = '0';
        int flips = 0;
        for (char ch : target.toCharArray()) {
            if (ch != curState) {
                flips++;
                curState = ch;
            }
        }
        return flips;
    }
}

var minFlips = function(target) {
    let curState = "0";
    let flips = 0;
    for (const ch of target) {
        if (ch !== curState) {
            flips++;
            curState = ch;
        }
    }
    return flips;
};
